public long catalan(int n) {
    long[] c = new long[n + 1];
    c[0] = 1;
    for (int k = 1; k <= n; k++) {
        long sum = 0;
        for (int i = 0; i < k; i++) {
            sum += c[i] * c[k - 1 - i]; // indices sum to k-1
        }
        c[k] = sum;
    }
    return c[n];
}

// Modular variant for large n (prime p):
public long catalanMod(int n, long p) {
    long[] c = new long[n + 1];
    c[0] = 1 % p;
    for (int k = 1; k <= n; k++) {
        long sum = 0;
        for (int i = 0; i < k; i++) {
            sum = (sum + c[i] * c[k - 1 - i]) % p; // mod after each add
        }
        c[k] = sum;
    }
    return c[n];
}

