def catalan_mod(self, n: int, p: int) -> int:
    c = [0] * (n + 1)
    c[0] = 1 % p
    for k in range(1, n + 1):
        total = 0
        for i in range(k):
            total = (total + c[i] * c[k - 1 - i]) % p
        c[k] = total
    return c[n]

