// Exact for small n (Cn fits in 64 bits, n <= 33).
public long catalanClosed(int n) {
    long result = 1;
    // C(2n, n) computed with divide-as-you-go to stay small.
    for (int i = 0; i < n; i++) {
        result = result * (2L * n - i) / (i + 1);
    }
    return result / (n + 1);
}

// Modular for large n (prime p > 2n), using precomputed tables.
public long catalanMod(int n, long p, long[] fact, long[] invFact) {
    long central = fact[2 * n] * invFact[n] % p * invFact[n] % p; // C(2n, n)
    long invNp1 = modpow(n + 1, p - 2, p);                        // (n+1)^(p-2)
    return central * invNp1 % p;                                  // multiply, never divide
}

private long modpow(long base, long exp, long mod) {
    long r = 1 % mod; base %= mod;
    while (exp > 0) {
        if ((exp & 1) == 1) r = r * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return r;
}

